/**
 * Central image registry.
 * Swap files in /public/images (or change the paths here) to replace any photo site-wide.
 *
 * Product photos are generated by `npm run images` from the /sarees folder.
 * Lifestyle photos are free-licence Unsplash images listed in scripts/stock-photos.txt.
 */

const PRODUCT_DIR = '/images/products';
const LIFESTYLE_DIR = '/images/lifestyle';

/** Product photo. variant: '' (full view) | 'd1' (body & motifs) | 'd2' (border & pallu) */
export function productImage(id, variant = '') {
  const base = `${PRODUCT_DIR}/${id}${variant ? `-${variant}` : ''}`;
  return {
    src: `${base}-960.webp`,
    srcSet: `${base}-480.webp 480w, ${base}-960.webp 960w`,
    width: 960,
    height: 1280,
  };
}

// Natural size (at 1800px wide source) of every lifestyle photo, used to prevent layout shift.
