  'black-silver-saree': [1800, 2700],
  'blue-silk-seated': [1800, 1195],
  'bridal-ivory-red': [1800, 2699],
  'craft-gold-embroidery': [1800, 2700],
  'craft-ikat-border': [1800, 1200],
  'craft-red-silk': [1800, 1350],
